// runScripts is used to copy and execute a set of scripts
func runScripts(ctx context.Context, o provisioners.UIOutput, comm communicator.Communicator, scripts []io.ReadCloser) error {
	timeout := comm.Timeout()
	retryCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	log.Printf("[DEBUG] waiting up to %s for remote-exec connection", timeout)

	// Wait and retry until we establish the connection
	err := communicator.Retry(retryCtx, func() error {
		return comm.Connect(o)
	})
	if err != nil {
		return err
	}

	// Wait for the context to end and then disconnect
	go func() {
		<-ctx.Done()
		comm.Disconnect()
	}()

	for scriptIndex, script := range scripts {
		outR, outW := io.Pipe()
		errR, errW := io.Pipe()
		defer outW.Close()
		defer errW.Close()

		go func(reader io.Reader) {
			lineReader := linereader.New(reader)
			for line := range lineReader.Ch {
				o.Output(line)
			}
		}(outR)
		go func(reader io.Reader) {
			lineReader := linereader.New(reader)
			for line := range lineReader.Ch {
				o.Output(line)
			}
		}(errR)

		remotePath := comm.ScriptPath()
		scriptReader := io.Reader(script)
		scriptSize := int64(0)
		scriptOrigin := "inline"

		switch src := script.(type) {
		case *os.File:
			scriptOrigin = src.Name()
			info, statErr := src.Stat()
			if statErr == nil {
				scriptSize = info.Size()
			}
			log.Printf("[DEBUG] remote-exec script %d source=%s size=%d path=%s", scriptIndex, scriptOrigin, scriptSize, remotePath)
		default:
			var contents bytes.Buffer
			copied, copyErr := io.Copy(&contents, script)
			if copyErr != nil {
				return fmt.Errorf("Failed to upload script: %v", copyErr)
			}
			scriptSize = copied
			scriptReader = bytes.NewReader(contents.Bytes())
			log.Printf("[DEBUG] remote-exec script %d source=%s size=%d path=%s", scriptIndex, scriptOrigin, scriptSize, remotePath)
		}

		if scriptSize == 0 {
			log.Printf("[WARN] remote-exec script %d is empty before upload to %s", scriptIndex, remotePath)
		}

		if err := comm.UploadScript(remotePath, scriptReader); err != nil {
			return fmt.Errorf("Failed to upload script: %v", err)
		}

		cmd := &remote.Cmd{
			Command: remotePath,
			Stdout:  outW,
			Stderr:  errW,
		}
		if err := comm.Start(cmd); err != nil {
			return fmt.Errorf("Error starting script: %v", err)
		}

		if waitErr := cmd.Wait(); waitErr != nil {
			if exitErr, ok := waitErr.(*remote.ExitError); ok {
				if exitErr.ExitStatus != 0 {
					log.Printf("[ERROR] remote command %q exited with status %d", exitErr.Command, exitErr.ExitStatus)
					return waitErr
				}
				log.Printf("[ERROR] remote command %q failed: %v", exitErr.Command, exitErr.Err)
			}
			return waitErr
		}

		empty := bytes.NewReader([]byte(""))
		if err := comm.Upload(remotePath, empty); err != nil {
			log.Printf("[WARN] Failed to upload empty follow up script: %v", err)
		}
	}

	return nil
}

